<script setup lang="ts">
import { computed } from 'vue'; import { Share2, Trophy } from 'lucide-vue-next'; import { useGameStore } from '../stores/game'
const store=useGameStore(); const totals=computed(()=>store.state?.history.reduce((a,s)=>({matches:a.matches+s.matches,goals:a.goals+s.goals,assists:a.assists+s.assists}),{matches:0,goals:0,assists:0})??{matches:0,goals:0,assists:0})
async function share(){ const text=`${store.state?.player.name}: ${totals.value.matches} partidos, ${totals.value.goals} goles y ${store.state?.player.titles} títulos en Copero.`; if(navigator.share) await navigator.share({title:'Mi carrera en Copero',text}); else await navigator.clipboard.writeText(text) }
</script>
<template><main v-if="store.state" class="summary-shell"><div class="brand light">COPERO</div><section><p>EL LEGADO DE</p><h1>{{ store.state.player.name }}</h1><p class="years">16 — {{ store.state.player.age }} AÑOS</p><div class="legacy-grid"><div><strong>{{ totals.matches }}</strong><span>PARTIDOS</span></div><div><strong>{{ totals.goals }}</strong><span>GOLES</span></div><div><strong>{{ totals.assists }}</strong><span>ASISTENCIAS</span></div><div><strong>{{ store.state.player.titles }}</strong><span>TÍTULOS</span></div><div><strong>{{ store.state.player.injuries }}</strong><span>LESIONES</span></div><div><strong>{{ store.state.player.wealth.toFixed(1) }}M</strong><span>PATRIMONIO</span></div></div><blockquote>“El talento abrió la puerta.<br/>Tus decisiones construyeron la historia.”</blockquote><button class="share" @click="share"><Share2 :size="18"/> COMPARTIR MI CARRERA</button><button class="new-career" @click="store.reset()"><Trophy :size="16"/> Crear otra leyenda</button></section></main></template>
